package com.nullo.voidapp.core.model

/** Represents a message in a conversation. */
sealed class Message(open val id: Long?) {

    /** A message sent by the user to the AI. */
    data class Prompt(
        override val id: Long,
        val query: String,
        val images: List<ImageAttachment> = emptyList()
    ) : Message(id)

    /** A text response generated by the AI, optionally including reasoning. */
    data class Completion(
        override val id: Long,
        val text: String,
        val reasoning: String? = null,
        val isStreaming: Boolean = false,
    ) : Message(id)

    /** An AI response containing generated images. */
    data class Images(
        override val id: Long,
        val caption: String? = null,
        val images: List<GeneratedImage>
    ) : Message(id)

    /** Represents an error returned while processing a request. */
    data class Error(
        override val id: Long,
        val text: String
    ) : Message(id)

    /**
     * Indicates that an AI response was interrupted before completion.
     * @param promptId prompt id for retry.
     * */
    data class Interrupted(
        override val id: Long,
        val promptId: Long,
    ) : Message(id)

    /** Indicates that an AI response is currently being generated. */
    data object Loading : Message(id = null)

    /** Indicates that images are currently being generated. */
    data object ImageLoading : Message(id = null)
}

/** Represents an image attached to a user prompt. */
data class ImageAttachment(
    val fileUri: String,
    val mimeType: String
)

/** Represents an image generated by the AI. */
data class GeneratedImage(
    val base64Data: String,
    val mimeType: String = "image/png",
)
